   114→    funcName: string,
   115→    argTypes: string[],
   116→    expectedParams: Record<string, string>,
   117→    expectedParamNames: string[]
   118→  ): TypeCheckResult {
   119→    // Phase 14-2: Check cache first (O(1) lookup)
   120→    const cache = getGlobalTypeCheckCache();
   121→    const paramTypesList = expectedParamNames.map(name => expectedParams[name]);
   122→    const cachedResult = cache.get(funcName, argTypes, paramTypesList);
   123→
   124→    if (cachedResult !== null) {
   125→      return cachedResult;
   126→    }
   127→
   128→    // Cache miss - perform full type check
   129→    let result: TypeCheckResult;
   130→
   131→    // Check parameter count
   132→    if (argTypes.length !== expectedParamNames.length) {
   133→      result = {
   134→        compatible: false,
   135→        message: `Function '${funcName}' expects ${expectedParamNames.length} arguments, got ${argTypes.length}`,
   136→        details: {
   137→          expected: `${expectedParamNames.length} parameters`,
   138→          received: `${argTypes.length} arguments`
   139→        }
   140→      };
   141→      this.trackError(funcName, result);
   142→    } else {
   143→      // Check each parameter type
   144→      let allCompatible = true;
   145→      for (let i = 0; i < expectedParamNames.length; i++) {
   146→        const paramName = expectedParamNames[i];
   147→        const expectedType = expectedParams[paramName];
   148→        const providedType = argTypes[i];
   149→
   150→        if (expectedType && !TypeParser.areTypesCompatible(expectedType, providedType)) {
   151→          result = {
   152→            compatible: false,
   153→            message: `Parameter '${paramName}' expects ${expectedType}, got ${providedType}`,
   154→            details: {
   155→              expected: expectedType,
   156→              received: providedType,
   157→              paramName,
   158→              paramIndex: i
   159→            }
   160→          };
   161→          this.trackError(funcName, result);
   162→          allCompatible = false;
   163→          break;
   164→        }
   165→      }
   166→
   167→      // All checks passed
   168→      if (allCompatible) {
   169→        result = {
   170→          compatible: true,
   171→          message: `Function '${funcName}' call is type-safe`
   172→        };
   173→      }
   174→    }
   175→
   176→    // Phase 14-2: Store result in cache
