   182→   * Check type assignment compatibility
   183→   * Can source type be assigned to target type?
   184→   */
   185→  checkAssignment(paramName: string, paramType: string, argType: string): TypeCheckResult {
   186→    const compatible = TypeParser.areTypesCompatible(paramType, argType);
