    // 2.4. Compile-Time-ORM: @db_table struct 스캔 → SQL 컴파일 타임 생성
    // generateORMMeta는 런타임 이전 실행 → 런타임 SQL 파싱 오버헤드 0
    const ormMetas = generateORMMeta(module as any);
    if (ormMetas.length > 0) {
      registerORMMeta(ormMetas);
