    // 예: math.add(1, 2) → qualified name으로 처리
    const calleeNameWithContext = this.resolveCalleeForModule(node.callee);
    out.push({ op: Op.CALL, arg: calleeNameWithContext, sub: [] });
  }
  break;

// ── Range/Iterator (Lazy Evaluation) ─────────────────────
